#!/bin/bash
# Uninstall script for AWS Client VPN
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling AWS Client VPN..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping AWS Client VPN if running..."
pkill -f "AWS Client VPN" 2>/dev/null || true

# Unload service com.amazonaws.acvc.helper
echo "Unloading service com.amazonaws.acvc.helper..."
launchctl unload -w /Library/LaunchAgents/com.amazonaws.acvc.helper.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.amazonaws.acvc.helper.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.amazonaws.acvc.helper.plist 2>/dev/null || true

# Unload service com.amazonaws.acvc.osx.core
echo "Unloading service com.amazonaws.acvc.osx.core..."
launchctl unload -w /Library/LaunchAgents/com.amazonaws.acvc.osx.core.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.amazonaws.acvc.osx.core.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.amazonaws.acvc.osx.core.plist 2>/dev/null || true

# Kill application with bundle ID com.amazonaws.acvc.osx if running
echo "Stopping application with bundle ID com.amazonaws.acvc.osx if running..."
killall -9 "com.amazonaws.acvc.osx" 2>/dev/null || true

# Remove $HOME/.config/AWSVPNClient
echo "Removing $HOME/.config/AWSVPNClient..."
if [ -d "$HOME/.config/AWSVPNClient" ]; then
    rm -rf "$HOME/.config/AWSVPNClient" 2>/dev/null || true
elif [ -f "$HOME/.config/AWSVPNClient" ]; then
    rm -f "$HOME/.config/AWSVPNClient" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.amazonaws.acvc.osx.plist
echo "Removing $HOME/Library/Preferences/com.amazonaws.acvc.osx.plist..."
if [ -d "$HOME/Library/Preferences/com.amazonaws.acvc.osx.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.amazonaws.acvc.osx.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.amazonaws.acvc.osx.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.amazonaws.acvc.osx.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState
echo "Removing $HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.amazonaws.acvc.osx.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
